export interface HalEngineConfig {
  provider: ProviderConfig;
  prompt: PromptBuilderConfig;
  tools?: ToolRegistry;
  session?: SessionStore;
  transport?: {
    port?: number;
    corsOrigin?: string | string[];
    basePath?: string;
    heartbeatIntervalMs?: number;
    additionalRoutes?: HalAppOptions['additionalRoutes'];
    rootRoutes?: HalAppOptions['rootRoutes'];
    errorHandler?: HalAppOptions['errorHandler'];
  };
  auth: {
    ws: WsAuthenticator;
    http?: HttpAuthMiddleware;
  };
  orchestrator?: {
    maxToolRounds?: number;
    contextConfig?: Partial<ContextConfig>;
    /** Lifecycle hooks: called before and after each phase of processing a user message. */
    hooks?: OrchestratorHooks;
  };
  // Replaces the package's logger process-wide, not per engine: there is one `log` per process.
  logger?: Logger;
  onConnect?: (session: ChatSession) => void | Promise<void>;
  onDisconnect?: (sessionId: string) => void | Promise<void>;
}

export interface HalEngine extends HalServer {
  app: ReturnType<typeof createApp>;
  orchestrator: ReturnType<typeof createChatOrchestrator>;
  toolRegistry: ToolRegistry;
}

export function createHalEngine(config: HalEngineConfig): HalEngine {
  // Before anything else builds, so a supplied logger receives this engine's first line.
  if (config.logger) setLogger(config.logger);

  const toolRegistry = config.tools ?? new ToolRegistry();
  const sessionStore = config.session ?? new InMemorySessionStore();
  const basePath = config.transport?.basePath ?? '/hal';

  const provider = createProvider(config.provider);
  const promptBuilder = new PromptBuilder(config.prompt);
  const orchestrator = createChatOrchestrator(provider, promptBuilder, toolRegistry, {
    maxToolRounds: config.orchestrator?.maxToolRounds,
    contextConfig: config.orchestrator?.contextConfig,
    hooks: config.orchestrator?.hooks,
    sessionStore,
  });

  const app = createApp({
    corsOrigin: config.transport?.corsOrigin,
    basePath,
    authMiddleware: config.auth.http,
    orchestrator,
    sessionStore,
    additionalRoutes: config.transport?.additionalRoutes,
    rootRoutes: config.transport?.rootRoutes,
    errorHandler: config.transport?.errorHandler,
  });

  const halServer = createServer({
    app,
    wsAuth: config.auth.ws,
    sessionStore,
    orchestrator,
    toolRegistry,
    basePath,
    port: config.transport?.port,
    heartbeatIntervalMs: config.transport?.heartbeatIntervalMs,
    onConnect: config.onConnect,
    onDisconnect: config.onDisconnect,
  });

  return {
    ...halServer,
    app,
    orchestrator,
    toolRegistry,
  };
}
import type {AIProvider, MessageChunk, SendMessageParams, StructuredOutputParams} from '../../types/ai.js';

export interface MockConfig {
  type: 'mock';
  structuredResponses?: Map<string, unknown>;
}

export function createMockProvider(config?: MockConfig): AIProvider {
  const structuredResponses = config?.structuredResponses ?? new Map<string, unknown>();

  return {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : 'Hello';

      const response = `Mock response to: "${userText}"`;

      for (const word of response.split(' ')) {
        yield {type: 'text', text: word + ' '};
      }

      yield {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 10, outputTokens: 20, totalTokens: 30}};
    },

    async generateStructured<T>(params: StructuredOutputParams<T>): Promise<T> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : '';

      const preconfigured = structuredResponses.get(userText);
      if (preconfigured !== undefined) return preconfigured as T;

      return buildDefaultResponse(params.responseSchema) as T;
    },
  };
}

// Factories, not values: `array` must hand back a fresh [] to each caller.
const SCALAR_DEFAULTS: Record<string, () => unknown> = {
  array: () => [],
  string: () => '',
  number: () => 0,
  boolean: () => false,
};

function buildDefaultResponse(schema: {type: string; properties?: Record<string, {type: string}>}): unknown {
  if (schema.type === 'object') {
    const result: Record<string, unknown> = {};
    for (const [key, prop] of Object.entries(schema.properties ?? {})) {
      result[key] = buildDefaultResponse(prop);
    }
    return result;
  }

  const scalar = SCALAR_DEFAULTS[schema.type];
  return scalar ? scalar() : null;
}
